@media print {
                  @page { size: A4 portrait; margin: 10mm; }
                  body > *:not(#__bulletin-print-root) { display: none !important; }
                  #__bulletin-print-root {
                    display: block !important;
                    position: static !important;
                    padding: 0 !important;
                    margin: 0 !important;
                    background: #fff !important;
                    color: #000 !important;
                    font-size: 10pt !important;
                    width: 100% !important;
                  }
                  #__bulletin-print-root .no-print { display: none !important; }
                  #__bulletin-print-root * {
                    -webkit-print-color-adjust: exact !important;
                    print-color-adjust: exact !important;
                  }
                  #__bulletin-print-root .rounded,
                  #__bulletin-print-root .rounded-md,
                  #__bulletin-print-root .rounded-lg {
                    page-break-inside: avoid !important;
                    break-inside: avoid !important;
                  }
                }

